import{_ as e,c as r,o as i,ah as n}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"8、【比】 坤下坎上","description":"溫公易說 - 8、【比】 坤下坎上","frontmatter":{"title":"8、【比】 坤下坎上","description":"溫公易說 - 8、【比】 坤下坎上"},"headers":[],"relativePath":"classics/wengong/009.md","filePath":"classics/wengong/009.md"}'),l={name:"classics/wengong/009.md"};function t(h,a,s,o,d,c){return i(),r("div",null,[...a[0]||(a[0]=[n('<h1 id="_8、【比】-坤下坎上" tabindex="-1">8、【比】 坤下坎上 <a class="header-anchor" href="#_8、【比】-坤下坎上" aria-label="Permalink to “8、【比】 坤下坎上”">​</a></h1><h3 id="彖曰-比-吉也-比-輔也。下順從也。原筮-元永貞-無咎-以剛中也。不寜方來-上下應也。後夫兇-其道窮也。" tabindex="-1">彖曰：比，吉也，比，輔也。下順從也。原筮，元永貞，無咎，以剛中也。不寜方來，上下應也。後夫兇，其道窮也。 <a class="header-anchor" href="#彖曰-比-吉也-比-輔也。下順從也。原筮-元永貞-無咎-以剛中也。不寜方來-上下應也。後夫兇-其道窮也。" aria-label="Permalink to “彖曰：比，吉也，比，輔也。下順從也。原筮，元永貞，無咎，以剛中也。不寜方來，上下應也。後夫兇，其道窮也。”">​</a></h3><p>比吉，比之所以吉者何？雜卦曰：比樂，師憂。凡物，孤則危，群則強。比者，上下相親，他不能間，外不能侵者也。故吉。原筮者何？比者，不可茍合也。是故。初六曰：有孚，比之，無咎。夫初六比之始也，始謀相親者，不可不謹擇其人。人之誠信未孚而親愛之，取禍之道也。故曰：有孚，比之，無咎。繫辭曰：君子易其心而後語，定其交而後求，此之謂也。原筮，元永貞，無咎者何？凡比之道，不可以不善也，不可以不長也，不可以不正也。故曰：原筮，元永貞，無咎。夫物比而不以剛中，則柔邪也。故彖曰：原筮，元永貞，無咎，以剛中也。</p><h3 id="象曰-地上有水-比。先王以建萬國-親諸侯。" tabindex="-1">象曰：地上有水，比。先王以建萬國，親諸侯。 <a class="header-anchor" href="#象曰-地上有水-比。先王以建萬國-親諸侯。" aria-label="Permalink to “象曰：地上有水，比。先王以建萬國，親諸侯。”">​</a></h3><h3 id="初六-有孚-比之-無咎。有孚盈缶-終來有他吉。-象曰-比之初六-有他吉也。" tabindex="-1">初六：有孚，比之，無咎。有孚盈缶，終來有他吉。 象曰：比之初六，有他吉也。 <a class="header-anchor" href="#初六-有孚-比之-無咎。有孚盈缶-終來有他吉。-象曰-比之初六-有他吉也。" aria-label="Permalink to “初六：有孚，比之，無咎。有孚盈缶，終來有他吉。 象曰：比之初六，有他吉也。”">​</a></h3><h3 id="六二-比之-自內-貞吉。-象曰-比之自內-不自失也。" tabindex="-1">六二：比之，自內，貞吉。 象曰：比之自內，不自失也。 <a class="header-anchor" href="#六二-比之-自內-貞吉。-象曰-比之自內-不自失也。" aria-label="Permalink to “六二：比之，自內，貞吉。 象曰：比之自內，不自失也。”">​</a></h3><h3 id="六三-比之匪人。-象曰-比之匪人-不亦傷乎" tabindex="-1">六三：比之匪人。 象曰：比之匪人，不亦傷乎？ <a class="header-anchor" href="#六三-比之匪人。-象曰-比之匪人-不亦傷乎" aria-label="Permalink to “六三：比之匪人。 象曰：比之匪人，不亦傷乎？”">​</a></h3><h3 id="六四-外比之-貞吉。-象曰-外比於賢-以從上也。" tabindex="-1">六四：外比之，貞吉。 象曰：外比於賢，以從上也。 <a class="header-anchor" href="#六四-外比之-貞吉。-象曰-外比於賢-以從上也。" aria-label="Permalink to “六四：外比之，貞吉。 象曰：外比於賢，以從上也。”">​</a></h3><p>外比者，何棄親而從疏也？棄親而從疏者，非親賢而從上，則不可也。親賢而從上者，茍不出乎正，猶不免乎兇也。夫比，非大公之道也。子曰：君子周而不比，小人比而不周。故比而不中正者，皆非君子之道也。</p><h3 id="九五-顯比-王用三驅-失前禽-邑人不誡-吉。-象曰-顯比之吉-位正中也。舍逆取順-失前禽也。邑人不誡-上使中也。" tabindex="-1">九五：顯比，王用三驅，失前禽，邑人不誡，吉。 象曰：顯比之吉，位正中也。舍逆取順，失前禽也。邑人不誡，上使中也。 <a class="header-anchor" href="#九五-顯比-王用三驅-失前禽-邑人不誡-吉。-象曰-顯比之吉-位正中也。舍逆取順-失前禽也。邑人不誡-上使中也。" aria-label="Permalink to “九五：顯比，王用三驅，失前禽，邑人不誡，吉。 象曰：顯比之吉，位正中也。舍逆取順，失前禽也。邑人不誡，上使中也。”">​</a></h3><p>九五顯比吉何也？九五履至貴之位，為眾陰所歸，暢其中正以懷海內。從命者賞，違命者誅。善善惡惡而不在於私，用中正以求比者也。故曰：顯比吉。顯者，光顯盛大之謂也。王用三驅，失前禽者何？背去之禽也。失者何？求與之相親而不可得者也。</p><h3 id="上六-比之無首-兇。-象曰-比之無首-無所終也。" tabindex="-1">上六：比之無首，兇。 象曰：比之無首，無所終也。 <a class="header-anchor" href="#上六-比之無首-兇。-象曰-比之無首-無所終也。" aria-label="Permalink to “上六：比之無首，兇。 象曰：比之無首，無所終也。”">​</a></h3>',12)])])}const m=e(l,[["render",t]]);export{b as __pageData,m as default};
